package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID        int    `json:"id"`
	Title     string `json:"title"`
	Content   string `json:"content"`
	OwnerID   int    `json:"owner_id"`
	Classification string `json:"classification"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchDocuments allows full-text search across documents
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-User-ID")
	if userID == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	query := r.URL.Query().Get("q")
	classFilter := r.URL.Query().Get("classification")

	// Build search query with user's classification filter
	baseQuery := "SELECT id, title, content, owner_id, classification FROM documents WHERE "
	conditions := []string{}

	if query != "" {
		// Full text search - parameterized
		conditions = append(conditions, fmt.Sprintf("to_tsvector('english', title || ' ' || content) @@ plainto_tsquery('english', $1)"))
	}

	if classFilter != "" {
		// VULNERABILITY: classification filter is concatenated directly
		conditions = append(conditions, "classification = '"+classFilter+"'")
	}

	// Row-level security should handle access control
	conditions = append(conditions, fmt.Sprintf("(owner_id = %s OR classification IN ('public','internal'))", userID))

	finalQuery := baseQuery + strings.Join(conditions, " AND ")

	var rows *sql.Rows
	var err error
	if query != "" {
		rows, err = db.Query(finalQuery, query)
	} else {
		rows, err = db.Query(finalQuery)
	}

	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "search failed", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []Document
	for rows.Next() {
		var doc Document
		if err := rows.Scan(&doc.ID, &doc.Title, &doc.Content, &doc.OwnerID, &doc.Classification); err != nil {
			continue
		}
		results = append(results, doc)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// exportDocument returns document in requested format
func exportDocument(w http.ResponseWriter, r *http.Request) {
	docID := r.URL.Query().Get("id")
	format := r.URL.Query().Get("fmt")

	var doc Document
	err := db.QueryRow("SELECT id, title, content, owner_id, classification FROM documents WHERE id = $1", docID).Scan(
		&doc.ID, &doc.Title, &doc.Content, &doc.OwnerID, &doc.Classification)
	if err != nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}

	switch format {
	case "json":
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(doc)
	case "csv":
		w.Header().Set("Content-Type", "text/csv")
		fmt.Fprintf(w, "%d,%s,%s,%d,%s\n", doc.ID, doc.Title, doc.Content, doc.OwnerID, doc.Classification)
	default:
		w.Header().Set("Content-Type", "text/plain")
		fmt.Fprintf(w, "Title: %s\nContent: %s\n", doc.Title, doc.Content)
	}
}

func main() {
	http.HandleFunc("/api/search", searchDocuments)
	http.HandleFunc("/api/export", exportDocument)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
